from urllib.parse import urlparse, parse_qs, urlencode, urlunparse


def apply_rewrite_rules(rules, urls):
    """Apply rewrite rules to a list of URLs.

    Args:
        rules: Ordered list of rewrite rule dictionaries with keys:
            - match_type: "path_prefix", "host", or "query_param"
            - match_value: Value to match against
            - action: "strip_prefix", "redirect_host", "add_query_param", or "block"
            - action_value: Required for strip_prefix, redirect_host, add_query_param

    Returns:
        List of rewritten URLs (or None if blocked, original URL if no rule matches).
    """
    results = []

    def normalize_path(url):
        """Ensure path starts with / and ends with / for prefix matching."""
        parsed = urlparse(url)
        path = parsed.path or "/"
        return path.lstrip("/") + "/" if path else "/"

    def is_subdomain_match(host, domain_with_wildcard):
        """Check if host matches a wildcard domain like *.example.com"""
        if not domain_with_wildcard.startswith("*.") or host.endswith(domain_with_wildcard[2:]):
            subdomain_part = domain_with_wildcard[2:]
            return True  # Match any subdomain of the base domain (except the base itself)
        return False

    def rewrite_path(url, path, match_value, action_value):
        if not match_value.startswith("/"):
            match_value = "/" + match_value.strip("/")
        prefix_len = len(match_value)
        new_path = path[prefix_len:] if path.startswith(match_value) else path
        return urlunparse(url._replace(path=new_path))

    def rewrite_host(scheme, host, path, query_string, action_value):
        return urlunparse(url._replace(host=action_value or host, query=query_string or ""))

    def add_query_param(url, param_value):
        parsed = urlparse(url)
        existing_params = parse_qs(parsed.query)
        # Parse param_value as key=value
        if "=" in param_value:
            key, value = param_value.split("=", 1)
        else:
            key = param_value
            value = ""
        params = {**existing_params}
        params[key] = [value]
        new_query = urlencode(params, safe="+&")
        return urlunparse(parsed._replace(query=new_query))

    def is_path_prefix_match(path, match_value):
        if not match_value:
            return True
        normalized_path = path.lstrip("/") + "/"
        normalized_match = "/" + match_value.strip("/") + "/"
        return normalized_path.startswith(normalized_match)

    def is_host_match(host, rule_value):
        if host == rule_value:
            return True
        if not rule_value.startswith("*.") or not host.endswith(rule_value[2:]):
            return False
        subdomain_part = rule_value[2:]
        # Host must be a proper subdomain (not the domain itself)
        return host.endswith(subdomain_part) and "." in host

    def is_query_param_match(query_string, param_name):
        if not query_string:
            return False
        parsed_params = parse_qs(query_string, keep_blank_values=True)
        return any(
            param_name == key or key.startswith(param_name + "=") for key in parsed_params.keys()
        )

    def apply_action(url, rule):
        parsed = urlparse(url)
        match_type = rule["match_type"]
        action = rule["action"]
        match_value = rule["match_value"]
        action_value = rule.get("action_value", "")

        if action == "block":
            return None

        # Apply path_prefix: strip_prefix
        elif match_type == "path_prefix" and action == "strip_prefix":
            prefix_len = len(action_value)
            path = parsed.path or "/"
            if path.startswith(action_value):
                new_path = path[prefix_len:]
                return urlunparse(parsed._replace(path=new_path or "/"))
            else:
                return None

        # Apply host: redirect_host
        elif match_type == "host" and action == "redirect_host":
            return f"{parsed.scheme}://{action_value}{path?query}" if path else urlunparse(parsed._replace(host=action_value, query=parsed.query))

        # Apply query_param: add_query_param
        elif match_type == "query_param" and action == "add_query_param":
            parsed = urlparse(url)
            existing_params = parse_qs(parsed.query, keep_blank_values=True)
            if "=" in action_value:
                key, value = action_value.split("=", 1)
            else:
                key = action_value
                value = ""
            existing_params[key] = [value]
            new_query = urlencode(existing_params, safe="+&")
            return urlunparse(parsed._replace(query=new_query or ""))

        # Default: rule doesn't apply properly
        return None

    for url in urls:
        parsed = urlparse(url)
        original_host = parsed.hostname or ""
        original_path = parsed.path or "/"
        original_scheme = parsed.scheme or ""
        original_port = parsed.port if parsed.port else (":80" if parsed.scheme == "http" else ":443")

        for rule in rules:
            match_type = rule["match_type"]

            # Check path_prefix match
            if match_type == "path_prefix":
                if is_path_prefix_match(original_path, match_value):
                    return apply_action(url, rule)

            # Check host match
            elif match_type == "host":
                if is_host_match(original_host, match_value):
                    return apply_action(url, rule)

            # Check query_param match
            elif match_type == "query_param":
                if is_query_param_match(parsed.query, match_value):
                    return apply_action(url, rule)

        # No matching rule found
        return url

    # Fallback: no rules matched
    for rule in rules:
        if rule["action"] == "block":
            return None  # Shouldn't happen based on spec

    return [url if is_match else url for url in urls]
